-- 5007 🏋️ Exercises from the book "creative-attacking-play-from-the-tactics-of-conte-allegri-simeone-mourinho-wenge" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'creative-attacking-play-from-the-tactics-of-conte-allegri-simeone-mourinho-wenge');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Twin-side combinations to receive between lines', 'combination', 'unopposed', 'in_possession', 48, 49, 'Session 1: Practice 1', 'Wenger (Arsenal)', 'Rehearse position-specific passing combinations that get a forward or No.10 receiving in the space between the opposition midfield and defensive lines, then finishing into a small goal.', 'Two thirds of a pitch with 4 mannequins (or tall cones) as defenders, 2 small goals, 2 white square zones in the pockets; 10 outfield players in their positions plus 2 extra players (A and B) near the goals; balls with the centre backs.', 'Two balls run at once, one each side from the centre backs. Left: CB 5 does a 1-2 with No.6, finds the full back 3 who has circled a pole, 3 goes inside to 6, 6 shifts and plays the dropping winger 11; 9 slides into the white square for a 1-2 with 11, who curls round the mannequin, plays forward to A, A sets first time for 9 to run on and score. Right: CB 4 does a 1-2 with No.8, full back 2 goes straight to winger 7, No.10 moves into the square for a 1-2 with 7, 7 feeds B who lays off first time for 10 to finish.', NULL, 'Swap in other combinations from the chapter analysis or your own; double up players in each position so the next one takes over.', 'Timing and synchronised movement are everything; 6 and 8 arrive on time to give the inside option while forwards time their move into the space behind the mannequins; quick accurate passing and sharp movement.', '10 outfield players + 2 extras (A, B)', 12, 24, '2/3 of a full pitch', NULL, NULL, NULL, true, false, true, NULL, 10),
  ('Build-up to find No.10 between lines', 'phase_of_play', 'overload', 'in_possession', 50, 52, 'Session 1: Practice 2', 'Wenger (Arsenal)', 'Moving the ball from the back line into the player positioned between the opposition''s midfield and defensive lines, then attacking the goal.', 'Two thirds of a pitch split into a back zone and a yellow zone between the lines; red back four plus 6 and 8 face 4 blue midfielders and 2 blue forwards, red 7, 9, 10, 11 further up, mannequins as the blue back four, full goal with GK at the top and 2 small goals behind the reds.', 'Coach feeds a red centre back; reds work the ball via a full back and a link player (often a winger) into No.10 in the yellow zone, who turns and slips the forward in to score. Blues try to win it and score in either small goal within 8-10 seconds.', 'Ball must go through a full back before entering the yellow zone.', 'Swap mannequins for passive then active defenders. 4-3-3 variation: either attacking midfielder (8 or 10) can receive in the yellow zone, the two rotating. 4-4-2 variation: the strong-side forward drops into the yellow zone while the other forward shifts across.', 'Use the full range of options to reach the player between the lines; pick the option based on how blues react.', '10 reds v 6 blues + 4 mannequins + GK', 17, 18, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Build-up between the lines zonal game', 'conditioned_game', 'opposed', 'in_possession', 53, 53, 'Session 1: Practice 3', 'Wenger (Arsenal)', 'Getting the ball to No.10 between the lines against live defenders and exploiting the space they leave when they step up.', 'Same 2/3-pitch zones as the previous practice, but the small goals become a full goal with a GK and the mannequins become 4 live blue defenders, 11 v 11.', 'Reds build from the back aiming to find No.10 in the yellow zone and attack the top goal; if a blue defender steps into the yellow zone to mark No.10, reds read it and attack the space he vacates (e.g. through ball out to the winger to cross).', 'Blue midfielders stay in their zone until a pass leaves it; blue defenders may enter the yellow zone to press No.10 and then move freely.', 'Adapt to 4-3-3 or 4-4-2 as in the previous practice''s variations.', 'Try every route into No.10 depending on how the defenders react.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Midfield combination with timed runs', 'passing_unopposed', 'unopposed', 'in_possession', 67, 67, 'Session 2: Practice 1', 'Klopp (Dortmund/Liverpool)', 'Synchronised passing and well-timed runs to receive in the space between the lines.', '40 x 50 yard area split in half, each half with a 20 x 5 yard yellow strip and 2 mannequins as opposing midfielders; players A-J on cones, both halves run at once with a ball each.', 'A passes to B as D pushes forward; B plays into C who dribbles on and passes to E, who drops and lays off to the advancing D; D must take it in the yellow strip, carry forward and switch to the other half where F-J repeat the pattern. Players rotate one position on.', NULL, NULL, 'Movements coordinated so receivers arrive at the right time and place; accurate passes; keep a high tempo.', '10 players', 10, 10, '40 x 50 yards', 45.7, 36.6, NULL, false, false, true, NULL, 40),
  ('Exploit 3v2 in midfield to small goals', 'passing_opposed', 'overload', 'in_possession', 68, 69, 'Session 2: Practice 2', 'Klopp (Dortmund/Liverpool)', 'Creating a 3v2 in central midfield by a dropping winger (or converging full back) and using it to find a midfielder between the lines.', '40 x 50 yard central area in 3 zones: 30 x 25 first zone, 30 x 15 yellow middle zone, 30 x 5 final zone with 3 small goals; red back four, 6 and 8, wingers 7 and 11 and No.10 in the final zone against 2 blue central midfielders.', 'Reds circulate at the back until a centre back carries forward; the strong-side winger (or full back, Guardiola-style) drops into the first zone to make 3v2. Reds play through link player No.10 to the forward-running No.8, who must take it in the yellow zone and finish into a small goal; alternatively release the overlapping full back to cross.', 'Blue players may never leave their zone.', '4-3-3 variation: add a centre forward (9) up top; the two attacking midfielders rotate between the first zone and the yellow zone and the 9 drops as link player.', 'Forward and wingers alert and moving to open lanes; use the overload to get time for a forward pass; accurate passing, coordinated movement, quick tempo.', '9 reds v 2 blues', 11, 12, '40 x 50 yards (30x25, 30x15, 30x5 zones)', 45.7, 36.6, NULL, true, false, true, NULL, 50),
  ('3v2 midfield overload functional practice', 'phase_of_play', 'overload', 'in_possession', 70, 71, 'Session 2: Practice 3', 'Klopp (Dortmund/Liverpool)', 'Creating and exploiting a numerical advantage in the centre to receive between the lines and attack the goal.', 'Two thirds of a pitch with a 35 x 25 yard central box (white 35 x 20, yellow 35 x 5 strip); red back four, 6, 8, No.10 in the yellow strip, wingers and a 9 against 2 blue central midfielders confined to the white zone, mannequins as the blue back line, full goal with GK.', 'Coach passes to a defender; reds move it until a centre back steps in with the ball, then the strong-side winger or full back enters the white zone for a 3v2. Reds use a link player (10 or a dropping 9) to find No.8 between the lines, then choose the best attacking option to score.', 'Blue players may not enter the yellow zone.', '4-3-3 variation: attacking midfielders 8 and 10 rotate between white and yellow zones, the 9 drops as link player.', 'Front players move into potential passing lanes; synchronised movement; play at high speed.', '10 reds v 2 blues + mannequins + GK', 13, 13, '2/3 pitch; 35 x 25 yard central box', 22.9, 32.0, NULL, true, true, true, NULL, 60),
  ('Read the winger''s reaction, play forward', 'phase_of_play', 'opposed', 'in_possession', 72, 73, 'Session 2: Practice 4', 'Guardiola (4-3-3), Klopp session', 'Choosing the right pass and movement based on whether the opposing winger tracks the converging full back.', 'As the previous practice on 2/3 of a pitch with the white and yellow central zones, now with 4 blue defenders and 2 blue wingers added; a coach in a red target zone at the halfway end.', 'Reds'' left back moves inside to create a 3v2. If the blue winger does not follow, play inside to the rotating 8/10 between the lines and attack; if he follows, switch out wide where the winger can go 1v1 and an attacking midfielder runs in behind the full back to receive and cross. Blues who win the ball counter and must pass to the coach in the red zone within 8 seconds.', 'Only one blue winger may enter the white zone; only one blue defender may enter the yellow zone; once blues win it everyone is free.', 'Can be adjusted to 4-2-3-1 or 4-4-2.', 'Defenders read the situation before choosing the forward pass (inside if 3v2 exists, wide if the winger follows); receivers in the yellow zone check and get told whether to turn or play first time.', '10 reds v 8 blues + GK + coach', 19, 20, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('3v2 in midfield 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 74, 74, 'Session 2: Practice 5', 'Klopp (Dortmund/Liverpool)', 'Exploiting the central overload to receive between the lines and attack in the final third in a full game.', '11 v 11 with full goals and goalkeepers at both ends, central white zone and yellow strip marked as before.', 'Reds aim to create and use a 3v2 in the white zone; blues defend, and on winning the ball counter and try to score within 8-10 seconds. A blue winger can step into the white zone at times to make it 3v3, so reds must adapt.', 'Only one blue winger inside the white zone and one blue defender inside the yellow zone when defending; free movement once blues have the ball.', NULL, NULL, '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Blind-side runs in behind, mannequins', 'combination', 'unopposed', 'in_possession', 83, 84, 'Session 3: Practice 1', 'Simeone (Atletico Madrid)', 'Passing and receiving behind the defensive line using runs on the blind side of centre backs.', '10 red outfield players in a 4-4-2 on cones against 10 blue mannequins; 2 white receiving areas behind the mannequin back line; GK in goal.', 'Centre backs swap passes until the moment to feed a full back or a dropping winger, who finds a central midfielder between the lines. If the midfielder gets it wide, the weak-side forward checks away then curls in behind the centre back''s blind side; if he gets it centrally, both forwards make blind-side runs. Medium-range pass into the white area, finish in two touches.', 'Forward finishes with no more than two touches.', 'Diagram 2 variation: midfielder receives centrally from a dropping winger and both forwards run in behind.', 'Synchronised, well-timed runs and accurate medium-range passing; forwards avoid offside.', '10 outfield + GK', 11, 11, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Read the full back: between or behind', 'combination', 'overload', 'in_possession', 85, 86, 'Session 3: Practice 2', 'Simeone (Atletico Madrid)', 'Reading the weak-side full back''s position to choose between a pass between the lines or a blind-side ball in behind.', 'As Practice 1 but two mannequins replaced by active blue full backs and the winger mannequins moved inside for a compact midfield; white receiving areas, GK.', 'The central midfielder receiving between the lines checks the weak-side full back: if he stays deep, play through to the winger between the lines to turn and play the final pass; if he steps up, hit the aerial pass over for the blind-side run of the forward.', NULL, '4-2-3-1 variation: one forward plus a deeper No.10; the 9 moves to the weak side once a strong side forms and runs off the centre back''s blind side.', 'Forward takes up a weak-side position after the first pass; midfielder reads the picture before deciding; synchronised runs and accurate passing.', '10 reds v 2 blues + mannequins + GK', 13, 13, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Blind-side runs against live back four', 'phase_of_play', 'overload', 'in_possession', 87, 87, 'Session 3: Practice 3', 'Simeone (Atletico Madrid)', 'Reading both full backs'' positions and taking the best attacking solution against a live back four.', 'As Practice 2 with two more mannequins replaced by live blue centre backs, so a full live back four; mannequins remain in midfield; white receiving areas; GK.', 'Midfielder receives from a winger or full back between the lines; both forwards open up on the blind side of the centre backs. Where a full back stays deep, avoid that side; where one steps up with a winger, play the aerial ball into the white area for the run in behind and finish.', 'Blue centre backs may not enter the white areas during the first phase, then defend freely.', 'Change to 4-2-3-1 as in Practice 2''s variation.', NULL, '10 reds v 4 blues + mannequins + GK', 15, 15, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Between or behind restricted game', 'conditioned_game', 'opposed', 'in_possession', 88, 88, 'Session 3: Practice 4', 'Simeone (Atletico Madrid)', 'Deciding between a through pass between the lines and a blind-side ball in behind in a full-team game.', 'Two full teams on 2/3 of a pitch; a yellow midfield zone 50 yards wide by 8-15 yards deep (depending on the midfielder''s level); optional white receiving areas; full goal with GK for reds to attack, 2 small goals for blues.', 'GK or coach starts to a centre back, who goes via a full back or dropping winger into a central midfielder in the yellow zone; he then either slides a pass between the lines or plays a medium-range pass behind a centre back for a forward. Blues who win it counter into the 2 small goals within 8-10 seconds.', 'Blue central midfielders may only enter the yellow zone after the ball is played into it.', 'Change to 4-2-3-1 as in Practice 2''s variation.', NULL, '11v11', 22, 22, '2/3 pitch; yellow zone 50 x 8-15 yards', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Between or behind 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 89, 89, 'Session 3: Practice 5', 'Simeone (Atletico Madrid)', 'Applying the between-the-lines or blind-side-run decision in a full game.', '11 v 11 on 2/3 of the pitch with two full-size goals and the yellow midfield zone.', 'Play always restarts with the red GK; same aims as the restricted game. If full backs stay deep and kill the blind-side pass, play into a winger moving inside between the lines and use quick combinations to exploit the space when a centre back steps out to him.', 'Same restrictions as the previous practice.', 'Change to 4-2-3-1.', NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Striker drops between lines, read centre back', 'combination', 'overload', 'in_possession', 102, 103, 'Session 4: Practice 1', 'Allegri (Juventus)', 'Create and use space in the centre when the No.9 drops off between the lines, deciding by the centre back''s reaction.', 'Two thirds of a pitch split into 9 zones with 6 mannequins as the opposition midfield and full backs; 2 live blue centre backs sit in a yellow zone in front of goal with a GK; black 2 CBs and 2 CMs in their half, wingers in wide red zones, No.10 in a middle red zone and No.9 in the yellow zone (4-2-3-1).', 'The CB on the striker''s side starts a 3-pass sequence ending with the near CM receiving while No.9 drops into the central red zone. If his marker stays, the CM plays to No.9''s feet to turn and pick one of three runners; if the marker follows, the CM passes into the vacated yellow-zone space for No.10 or a winger to run onto and finish; a quick passing combination can still beat a tight marker.', 'Defending centre backs may not enter other zones but can drop back to cover behind.', '4-4-2 version: either CM can end up on the ball and the striker on that side (9 or 10) drops into the middle red zone.', 'Passing accuracy, synchronised movement, reading the defender, decision making.', '8 attackers + GK v 2 defenders (+ mannequins)', 11, 14, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Winger drops in, full back exploits wide space', 'combination', 'overload', 'in_possession', 104, 105, 'Session 4: Practice 2', 'Allegri (Juventus)', 'Create and exploit space out wide when the strong-side winger drops between the lines, reading the opposing full back.', 'Same zoned 2/3-pitch layout as Practice 1, but black full backs start in wide blue zones; blue centre backs become mannequins and 2 live blue full backs stand in the white side zones.', 'After the CM receives, the strong-side winger drops into the white central zone. If the blue full back follows him, the CM plays a long/aerial ball into the space for the far or near black full back to run onto and cross; if he does not follow, the winger receives to feet, turns and chooses one of three forward passes. Every scenario ends with a shot at goal.', 'Passes to the full backs must be received inside the white side zones.', '4-4-2 version where either CM can receive and the winger on that side (7 or 11) drops; a tightly marked winger can still be found with a combination.', 'Read the full back''s reaction; timing of the overlapping run; accurate long passing.', '10 attackers + GK v 2 defenders (+ mannequins)', 13, 16, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Dropping-back movements functional game', 'phase_of_play', 'overload', 'in_possession', 106, 106, 'Session 4: Practice 3', 'Allegri (Juventus)', 'Use dropping movements of the forward or wingers to create space and exploit it in the centre or wide.', 'Two thirds of a pitch in 12 zones with 3 mannequins as the blue midfield; black 4-2-3-1 starts from its GK into a first zone with a 4v3 inside plus 3 outside support players (GK and two full backs in blue side zones); live blue back four and GK.', 'Black build out of the first zone looking for time to play forward; the player in front of the man on the ball (No.9 or a winger) drops off, and the passer reads his marker to play to feet or into the space left behind, then the team attacks the goal. A marked receiver means using a combination.', 'Defenders cannot leave their zones except to drop back and cover. If blue win it in the first zone they try to dribble through the end line to score.', 'Switch between 4-4-2 and 4-2-3-1.', 'Passer reads the defender: feet if not followed, space if followed.', 'approx. 11 v 8 + GKs', 18, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Dropping-back movements 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 107, 107, 'Session 4: Practice 4', 'Allegri (Juventus)', 'Apply forward and winger dropping movements to create and exploit space in a full 11v11.', '11 v 11 on two thirds of a pitch; first zone and wide blue zones removed, a full-size goal with GK added for the black team; zones still mark the defenders'' areas.', 'Black start from their GK and look for time to pass forward; the striker or winger drops, and the passer plays to feet or into the space created. If marked after receiving, black combine to exploit the space.', 'Defenders cannot enter other defenders'' zones but can drop back behind. On winning the ball blue must score within 8-10 seconds.', 'Change formation between 4-4-2 and 4-2-3-1.', NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Weak-side forward shifts across pattern 3-5-2', 'combination', 'unopposed', 'in_possession', 118, 119, 'Session 5: Practice 1', 'Conte (Juventus)', 'Rehearse creating an overload when the weak-side striker shifts across into his partner''s centre back zone.', '40 x 60 yard area with 6 marked boxes (2 red, 2 white, 2 yellow) and 8 mannequins, full goal and GK; 3-5-2 shape with players A (CBs), B (wing backs), C (CMs), No.9, No.10 and wide attacking mids 7 and 11.', 'A plays a one-two with C, then goes wide to B; B finds C inside a red box, who passes to the strong-side striker in a yellow box. The weak-side striker shifts across into a white box to receive the lay-back, drives forward and slips a final pass to 7 or 9 to score. Rotate A, B, C and repeat on the other side with roles of 9 and 10 swapped.', 'Receptions must happen inside the named boxes.', 'Overload prevented: assume the CB follows the shifting striker, so No.9 plays first time into the space behind for the weak-side midfielder (11) to receive in the yellow box and finish.', 'Midfielders ready for first-time pass or lay-off; sharp synchronised movements; speed and accuracy of passing.', 'about 11 + GK, 2 per position to keep tempo', 11, 18, '40 x 60 yards', 54.8, 36.6, NULL, true, true, true, NULL, 180),
  ('Forward shifts across pattern 4-4-2', 'combination', 'unopposed', 'in_possession', 120, 120, 'Session 5: Practice 2', 'Conte (Juventus)', 'Same shifting-forward overload pattern adapted to a 4-4-2 with wide wingers.', 'Same 40 x 60 yard box layout with mannequins, goal and GK; wingers 7 and 11 replace the narrow attacking midfielders.', 'A-C one-two, out to B, back into C in the red box; the weak-side striker drops and comes across to receive, turn and play a final ball to 7 or 9. When his marker is assumed to follow, C instead goes to the other striker as a link player to set No.11 running into the free yellow box, or plays straight to No.11.', 'Receptions inside the marked boxes.', 'Easily set up for 4-2-3-1 with the No.10 deeper on the weak side who simply shifts across.', NULL, 'about 11 + GK', 11, 18, '40 x 60 yards', 54.8, 36.6, NULL, true, true, true, NULL, 190),
  ('Forward-shift overload reading defenders'' reactions', 'combination', 'overload', 'in_possession', 121, 121, 'Session 5: Practice 3', 'Conte (Juventus)', 'Create the overload with a shifting forward and choose the pass from how the live defenders react.', 'Same 40 x 60 yard area as Practices 1-2; two live blue centre backs (4 and 5) in the white boxes and one live blue central midfielder added.', 'When C receives in the red box, the blue CM positions to block one striker, which decides on which side the overload is made. If the CB follows the dropping forward, C plays an aerial ball into the space behind for the attacking midfielder to receive in the yellow box and score; if not, the forward receives and turns in space.', 'Centre backs stay in their areas unless following a forward''s dropping movement.', NULL, NULL, '11 attackers + GK v 3 defenders', 15, 18, '40 x 60 yards', 54.8, 36.6, NULL, true, true, true, NULL, 200),
  ('Overload strong or weak side functional 3-5-2', 'phase_of_play', 'overload', 'in_possession', 122, 123, 'Session 5: Practice 4', 'Conte (Juventus)', 'Read the opposition and create the overload on the strong or weak side with a shifting forward.', 'Two thirds of a pitch; blue back four with GK (CBs in 8 x 10 yard white boxes), a blue CM and mannequins; black 3-5-2 with a coach on the ball at halfway.', 'Coach and back line circulate; when it reaches a wing back the black CM gets in position to receive. Depending on whether the blue CM blocks one forward and whether the CB follows, No.8 plays to No.9 for a lay-back to 10, to No.10''s feet to turn, or into the white area behind for No.11 (aerial or via the forward as a link). Black attack to score, blue defend.', 'Blue centre backs may not enter each other''s areas.', NULL, 'Read the situation to pick the next pass; attacking mids watch for free space to time runs; synchronised movement; quick accurate passing.', '10 + coach v 5 + GK', 16, 18, '2/3 of a full pitch; CB boxes 8 x 10 yards', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Overload strong or weak side functional 4-4-2', 'phase_of_play', 'overload', 'in_possession', 124, 124, 'Session 5: Practice 5', 'Conte (Juventus)', 'Create and exploit an overload with the weak-side forward shifting to the strong side, in a 4-4-2.', 'Same as Practice 4 but black use 2 CMs (6 and 8) and wide wingers 7 and 11.', 'If the blue CM blocks the diagonal pass, the overload is made on the strong side: No.9 drops across unmarked, the CM plays to the strong-side striker who sets it back to No.9, who turns in the yellow area and threads a pass between CB and FB for the winger''s run.', 'Blue centre backs may not enter each other''s areas.', NULL, NULL, '10 + coach v 5 + GK', 16, 18, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Forward shifting across zonal game', 'phase_of_play', 'opposed', 'in_possession', 125, 126, 'Session 5: Practice 6', 'Conte (Juventus)', 'Create overloads with the shifting forward against a full defence and midfield, with a counter-goal for defenders.', 'Two thirds of a pitch; coach in a 5 x 5 yard box; black CBs and CM start in a 20-yard white low zone; a 5-8 yard yellow zone holds the black wing backs and the 4 blue midfielders; blue back four + GK.', 'Coach plays to a black CB who looks to find the CM in space; black then score by creating the overload or using the space the defenders leave. Blue defend and on winning it pass back to the coach''s box within 8-10 seconds.', 'The 2 blue central midfielders cannot enter the white low zone while defending.', '4-4-2 variation with 2 CMs and 2 wide wingers; scenario where the CB does not follow and No.9 receives after a lay-off.', 'Read the situation for the next pass; attacking mids alert to free spaces and time their runs.', 'about 10 + coach v 8 + GK', 18, 20, '2/3 of a full pitch; low zone 20 yards long, coach box 5 x 5 yards', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Forward shifting across 11v11 zonal game', 'conditioned_game', 'opposed', 'in_possession', 127, 127, 'Session 5: Practice 7', 'Conte (Juventus)', 'Apply the shifting-forward overload in a full 11v11 with pressure on the build-up.', 'As Practice 6, plus a GK and full-size goal for the black team and 2 blue forwards pressing the black defenders in the white low zone.', 'Black build from the back and look for the CM to receive and play forward; when the dropping forward is followed, the space behind the CB is used, e.g. No.7 runs in behind from No.10''s pass to go 1v1 with the GK.', 'The 2 blue central midfielders cannot enter the white low zone while defending.', 'Switch to 4-4-2 with 2 CMs and 2 wingers.', NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Winger cuts inside overload pattern', 'combination', 'unopposed', 'in_possession', 135, 136, 'Session 6: Practice 1', 'Mourinho (Man Utd)', 'Rehearse an overload in the centre with the winger on the weak or strong side making a converging run inside.', '40 x 60 yard area with 2 yellow and 2 white receiving boxes, 8 large mannequins (or cones) as the opposition midfield and back line, full goal with GK; 4 x A (CBs), 2 x B (FBs), 2 x C (CMs), plus No.10, No.9 and wingers 7 and 11.', 'A plays to C; No.10 moves into the strong-side white box and No.9 takes the weak side. C goes back to A, A to B, while C shows in a yellow box to receive. C then plays to No.9 (lay-off to the inward-running winger) or straight to the winger, who drives on and plays a final pass to one of three runners to score.', 'Receive inside the marked boxes.', 'Strong-side version: No.10 on the weak side, No.9 on the strong side, and the strong-side winger (7) comes inside for the lay-off. Let 9 and 10 swap who drops. Repeat on the other side; 2 per advanced position for tempo.', 'Timing of synchronised movements; good passing technique and accuracy.', 'about 12 + GK', 12, 18, '40 x 60 yards', 54.8, 36.6, NULL, true, true, true, NULL, 250),
  ('Winger cuts inside, read full back', 'combination', 'overload', 'in_possession', 137, 137, 'Session 6: Practice 2', 'Mourinho (Man Utd)', 'Create the winger''s overload and react when it is blocked by a following full back.', 'As Practice 1, plus two 10 x 15 yard red zones out wide; two live blue full backs replace the wide mannequins.', 'C decides strong or weak side from No.9''s position and the full back''s reaction. If the full back stays, play runs as Practice 1; if he tracks the winger inside, C switches into the wide red zone for B to receive, advance and cross for 9, 10 and 7.', 'Wide pass must be received in the 10 x 15 yard red zone.', NULL, NULL, 'about 12 + GK v 2', 14, 20, '40 x 60 yards; wide zones 10 x 15 yards', 54.8, 36.6, NULL, true, true, true, NULL, 260),
  ('Winger overload 10v4 plus GK', 'phase_of_play', 'overload', 'in_possession', 138, 139, 'Session 6: Practice 3', 'Mourinho (Man Utd)', 'Read the tactical situation to create the winger''s overload or use the wide space against a live back four.', 'Two thirds of a pitch; red team 10 outfield players in 4-2-3-1 against 4 midfield mannequins, 4 live blue defenders and a GK; white central boxes and red wide zones marked.', 'Coach passes to a CB, who goes wide to the full back, who finds the CM. The CM reads where No.9 is and the weak-side winger moves inside; the winger receives in the white area directly or from No.9''s lay-off and picks one of three runners for a 5v4 or 6v4.', 'Winger must receive inside the white area.', '4-4-2 version: overload made on either side; when the blue full back follows the winger, a long pass finds the red full back in the red wide zone to cross.', NULL, '10 v 4 + GK', 15, 16, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Winger overload functional practice', 'phase_of_play', 'overload', 'in_possession', 140, 141, 'Session 6: Practice 4', 'Mourinho (Man Utd)', 'Create the overload with the winger shifting inside against a defending midfield and back four, with a counter for defenders.', 'Two thirds of a pitch with a white low zone (red back four), a yellow zone holding 4 blue midfielders, 2 central white areas and 2 red side areas; coach in a blue box; blue back four + GK.', 'A CB receives from the coach, goes wide to the full back, who passes inside to the CM; the CM reads No.9''s side and the winger cuts in to receive directly or via No.9''s lay-off, then the team attacks. Blue defend and on winning it pass to the coach''s box within 8-10 seconds.', 'Blue midfielders stay inside the yellow zone until their team wins the ball.', '4-4-2 variation: overload on either side; when the full back follows the winger, the forward plays first time to the overlapping full back in the red area to cross.', NULL, '10 + coach v 8 + GK', 19, 20, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Winger overload 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 142, 142, 'Session 6: Practice 5', 'Mourinho (Man Utd)', 'Create and exploit the winger''s overload, or switch wide when it is blocked, in an 11v11.', 'As Practice 4, but play starts from the red GK in a full goal, and 2 blue forwards are added to press the build-up.', 'Red build from the back; if the winger''s run inside is tracked by his full back, the CM switches play into the free red side area for the full back to attack, often a 4v3. Blue score within 8-10 seconds after winning the ball.', 'Blue score within 8-10 seconds of winning possession; zone restrictions as Practice 4.', NULL, 'CM reads the situation and makes the best decision; accurate short and long passing, good first touch, turning, timed runs and synchronised movement.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 290)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
